create table public.egg_operational_result_recovery (run_id uuid primary key references public.egg_operational_auto_runs(id), finding jsonb not null check(jsonb_typeof(finding)='object'), created_at timestamptz not null default now()); alter table public.egg_operational_result_recovery enable row level security; revoke all on public.egg_operational_result_recovery from anon,authenticated; grant select,insert on public.egg_operational_result_recovery to service_role;
